@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');
:root{--ink:#080b0b;--panel:#101615;--line:#4e5e56;--paper:#e0e6dc;--muted:#87928a;--acid:#d4ff67;--red:#fa5946;--mono:'IBM Plex Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}
*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#080b0b;color:var(--paper);font-family:var(--mono);user-select:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100vw;height:100dvh;min-height:360px;overflow:hidden;background:#0b0e0d;isolation:isolate}#view{position:absolute;inset:0;width:100%;height:100%;display:block;image-rendering:pixelated;background:#101513}.scanlines,.vignette{position:absolute;inset:0;pointer-events:none;z-index:2}.scanlines{opacity:.16;background:repeating-linear-gradient(0deg,transparent 0px,rgba(0,0,0,.1) 1px,rgba(0,0,0,.1) 2px,transparent 3px,transparent 5px);mix-blend-mode:multiply}.vignette{background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.28) 72%,rgba(0,0,0,.74) 130%);box-shadow:inset 0 0 150px #0006}.topline{position:absolute;z-index:4;left:0;right:0;top:0;height:68px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d5ef5929;background:linear-gradient(180deg,rgba(5,9,8,.93),rgba(7,11,10,.64))}.brand{display:flex;align-items:center;gap:11px;font:800 18px var(--display);letter-spacing:2px}.brand-mark{display:grid;place-items:center;width:27px;height:27px;background:var(--acid);color:#111811;font:900 19px var(--display);clip-path:polygon(0 0,100% 0,100% 76%,72% 100%,0 100%)}.brand-dim{color:#87938b;margin-left:4px}.mission{font-size:10px;letter-spacing:1.55px;color:#aab4aa}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--red);margin:0 8px 1px 0;box-shadow:0 0 10px var(--red);animation:pulse 1.6s infinite}.mission-divider{color:#576159;margin:0 8px}.sound-toggle{border:0;background:none;color:var(--acid);font:600 10px var(--mono);letter-spacing:1px;cursor:pointer}.sound-toggle span{color:#aab4aa;margin-left:5px}.hud{position:absolute;z-index:3;top:82px;left:36px;right:36px;display:flex;justify-content:space-between;align-items:flex-start;text-shadow:0 2px 6px #000}.hud-left,.hud-right{width:230px}.hud-center{text-align:center;padding-top:1px}.stat-label,.weapon-label,.sector-label{font-size:10px;letter-spacing:1.5px;color:#c1cabd}.stat-label span{margin-left:8px;color:var(--acid);font-size:9px}.health-row{display:flex;align-items:center;gap:9px;margin-top:3px}.cross-icon{color:var(--acid);font-size:15px}.health-row strong{font:700 29px var(--display);letter-spacing:1px;min-width:40px}.meter,.armor-meter{width:106px;height:4px;background:#d9e3d326;transform:skewX(-20deg)}.meter i,.armor-meter i{display:block;width:100%;height:100%;background:var(--acid);box-shadow:0 0 8px #d4ff6755;transition:width .2s}.armor-row{display:flex;align-items:center;gap:7px;margin:2px 0 0 25px;color:#87928a;font-size:9px;letter-spacing:1px}.armor-row strong{font-weight:500;color:#bec8bf}.armor-meter{width:81px;height:3px}.armor-meter i{background:#91c7d0}.sector-label{color:#b4beb4}.sector-label span{color:var(--red);font-weight:700;margin-left:5px}.hud-center #objective{font:700 14px var(--display);letter-spacing:2px;color:var(--acid);margin-top:5px}.hud-right{text-align:right}.weapon-label{display:flex;justify-content:flex-end;align-items:center;gap:10px;font-size:9px}.weapon-label #weapon-index{color:#849087}.ammo-row{display:flex;align-items:baseline;justify-content:flex-end;gap:7px;margin-top:-3px}.ammo-row strong{font:800 39px var(--display);line-height:1}.ammo-slash{font:400 18px var(--display);color:#7b877e}.ammo-row>span:nth-child(3){font:600 18px var(--display);color:#bdc6bc}.ammo-label{font-size:9px;letter-spacing:1px;color:#89958b;margin-left:5px}.ammo-type{color:#859188;font-size:8px;letter-spacing:1.15px;margin-top:3px}.map-panel{position:absolute;z-index:3;right:35px;top:167px;width:132px;padding:7px 7px 5px;background:#080d0dcc;border:1px solid #c9e76f48;box-shadow:0 8px 28px #0005}.map-title{font-size:8px;letter-spacing:1px;color:#adb8ad;display:flex;justify-content:space-between;padding:1px 1px 5px}.map-title span:last-child{color:var(--acid)}#map{display:block;width:116px;height:116px;image-rendering:pixelated;background:#101714}.map-foot{font-size:7px;color:#778279;letter-spacing:1px;padding:5px 1px 0}.map-foot i{display:inline-block;width:5px;height:5px;background:var(--red);border-radius:50%;margin-right:5px}.bottom-hint{position:absolute;z-index:4;bottom:20px;left:36px;right:36px;display:flex;justify-content:space-between;align-items:center;color:#a1ada2;font-size:9px;letter-spacing:1px;text-shadow:0 2px 5px #000}.bottom-hint b{font-weight:400;color:#d4ff67;margin:0 7px}#pause-button{border:1px solid #c6d3c64a;background:#090e0dd9;padding:8px 11px;color:var(--acid);font-size:12px;cursor:pointer}#pause-button span{font-size:8px;letter-spacing:1px;color:#b9c3b9;margin-left:5px}.crosshair{position:absolute;z-index:3;top:50%;left:50%;width:24px;height:24px;transform:translate(-50%,-50%);pointer-events:none;opacity:.82}.crosshair i,.crosshair b,.crosshair em,.crosshair span{position:absolute;background:var(--acid);box-shadow:0 0 5px #000}.crosshair i,.crosshair b{height:1px;width:6px;top:11px}.crosshair i{left:0}.crosshair b{right:0}.crosshair em,.crosshair span{width:1px;height:6px;left:11px}.crosshair em{top:0}.crosshair span{bottom:0}.damage-flash{position:absolute;z-index:2;inset:0;pointer-events:none;background:radial-gradient(ellipse,transparent 30%,rgba(239,47,30,.4));opacity:0;transition:opacity .2s}.toast{position:absolute;z-index:6;left:50%;top:24%;transform:translate(-50%,-10px);padding:9px 14px;background:#0b1210e8;border:1px solid #d4ff6770;color:var(--acid);font-size:10px;letter-spacing:1.5px;opacity:0;transition:all .22s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.pickup-banner{position:absolute;z-index:4;left:50%;bottom:16%;transform:translateX(-50%);font:700 16px var(--display);letter-spacing:2px;color:var(--acid);text-shadow:0 2px 8px #000;opacity:0;transition:opacity .25s;pointer-events:none}.screen{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:rgba(5,8,7,.82);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s}.screen.visible{opacity:1;visibility:visible}.title-grid{position:absolute;inset:0;opacity:.13;background-image:linear-gradient(#9fb68a22 1px,transparent 1px),linear-gradient(90deg,#9fb68a22 1px,transparent 1px);background-size:50px 50px;mask-image:linear-gradient(90deg,black,transparent 80%)}.title-card{position:relative;width:min(560px,calc(100% - 44px));margin-left:-13vw;padding:33px 40px 30px;background:linear-gradient(120deg,#0b100fee,#111814ee 68%,#121a14dd);border:1px solid #c4e86c55;box-shadow:0 24px 100px #0009;clip-path:polygon(0 0,96% 0,100% 5%,100% 100%,4% 100%,0 96%)}.eyebrow{display:flex;align-items:center;gap:9px;font-size:9px;letter-spacing:1.4px;color:#a6b1a6}.eyebrow-line{height:1px;width:22px;background:var(--acid)}.report-id{margin-left:auto;color:#6b796e}.title-card h1{font:900 clamp(74px,10vw,112px)/.8 var(--display);letter-spacing:-3px;margin:24px 0 8px;color:#ebeee5;text-shadow:4px 5px 0 #344034}.title-card h1 span{display:block;color:var(--acid);font-size:.77em;letter-spacing:7px;margin-top:12px;text-shadow:3px 4px 0 #465836}.title-sub{font:700 15px var(--display);letter-spacing:3.2px;color:#b0bbae;margin-top:25px}.title-sub i{font-style:normal;color:var(--red)}.story{font:11px/1.85 var(--mono);color:#9ba79c;margin:18px 0 25px}.primary-button{position:relative;display:flex;align-items:center;justify-content:space-between;width:100%;min-height:49px;padding:0 15px 0 19px;border:0;background:var(--acid);color:#11170f;font:800 14px var(--display);letter-spacing:1.5px;cursor:pointer;clip-path:polygon(0 0,96% 0,100% 24%,100% 100%,0 100%);transition:background .18s,transform .18s}.primary-button:hover{background:#ecff9a;transform:translateY(-2px)}.primary-button b{font-size:21px;font-weight:600}.start-note{margin-top:15px;color:#78847a;font-size:8px;letter-spacing:1px;text-align:center}.keycap{display:inline-grid;place-items:center;width:17px;height:15px;border:1px solid #718071;margin-right:5px;color:#c0cbbc}.note-separator{margin:0 8px;color:#526052}.title-stamp{position:absolute;right:12%;top:25%;transform:rotate(11deg);border:3px solid #e24c377a;color:#e85c49a0;font:900 17px var(--display);letter-spacing:4px;text-align:center;padding:8px 13px}.title-stamp strong{font-size:46px;line-height:.9}.title-footer{position:absolute;bottom:22px;left:36px;right:36px;display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.1px;color:#778279}.title-footer i{font-style:normal;color:var(--acid);margin:0 4px}.modal-card{position:relative;width:min(430px,calc(100% - 40px));padding:33px 38px;background:#0c120fee;border:1px solid #c4e86c55;box-shadow:0 24px 90px #000b;text-align:center}.modal-card>.eyebrow{justify-content:center}.modal-card h2{font:900 54px/.95 var(--display);letter-spacing:2px;margin:20px 0 9px}.modal-card h2 span{color:var(--acid)}.modal-card p{color:#9ba79c;font-size:11px;margin:0 0 25px}.controls-list{display:grid;grid-template-columns:repeat(2,1fr);gap:10px 20px;margin-top:24px;text-align:left;border-top:1px solid #c2d0c122;padding-top:17px;font-size:9px;color:#d1d9cf}.controls-list i{float:right;color:#7f8e81;font-style:normal;font-size:8px}.result-stats{display:flex;justify-content:space-around;margin:22px 0 26px;padding:14px 0;border-top:1px solid #c2d0c122;border-bottom:1px solid #c2d0c122}.result-stats span{font-size:8px;letter-spacing:.7px;color:#89958b}.result-stats strong{display:block;margin-top:5px;font:700 25px var(--display);color:var(--acid)}#touch-controls{display:none}.touch-pad,.touch-actions{pointer-events:auto}.touch-pad button,.touch-actions button{border:1px solid #d4ff6760;background:#0b100dbb;color:#e1eccb;touch-action:none}.touch-pad>button{width:44px;height:37px;margin:0 0 3px 44px}.touch-pad div{display:flex;gap:3px}.touch-pad div button{width:42px;height:38px}.touch-actions{display:flex;align-items:flex-end;gap:10px}.touch-actions button{height:48px;min-width:48px}.touch-actions #touch-fire{width:76px;height:76px;border-radius:50%;background:#c91f18a8;border-color:#ff8c77;font:700 12px var(--mono);letter-spacing:1px}.touch-actions #touch-reload{font-size:21px;border-radius:50%}
@keyframes pulse{50%{opacity:.35;box-shadow:0 0 2px var(--red)}}
@media(max-width:700px){.topline{height:53px;padding:0 14px}.brand{font-size:15px;gap:7px}.brand-mark{width:23px;height:23px}.mission{font-size:8px;letter-spacing:.7px}.mission-divider{margin:0 3px}.sound-toggle{font-size:0}.sound-toggle span{font-size:8px;margin:0}.hud{top:64px;left:15px;right:15px}.hud-left,.hud-right{width:145px}.health-row strong{font-size:25px;min-width:35px}.meter{width:66px}.armor-meter{width:55px}.armor-row{margin-left:22px}.hud-center{display:none}.weapon-label{font-size:8px;gap:5px}.ammo-row strong{font-size:34px}.ammo-type{font-size:7px}.map-panel{top:auto;bottom:86px;right:12px;width:102px;padding:5px}.map-title{font-size:7px}#map{width:90px;height:90px}.map-foot{font-size:6px}.bottom-hint{left:14px;right:14px;bottom:15px;font-size:7px}#hint-text{max-width:70%;line-height:1.7}.bottom-hint b{margin:0 3px}#pause-button{padding:7px 8px;font-size:10px}.title-card{margin:0;padding:27px 24px;width:min(450px,calc(100% - 32px))}.title-card h1{font-size:82px}.title-card h1 span{font-size:.75em}.title-sub{font-size:12px;letter-spacing:2px}.story{font-size:10px}.title-stamp{right:6%;top:10%;transform:rotate(10deg) scale(.7)}.title-footer{left:15px;right:15px;font-size:7px}.start-note{font-size:7px}.modal-card{padding:27px 24px}.modal-card h2{font-size:45px}#touch-controls{position:absolute;z-index:5;left:13px;right:13px;bottom:76px;display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none;opacity:.78}.screen.visible~#touch-controls{opacity:0;pointer-events:none}.touch-pad button{height:34px}.touch-pad div button{height:34px;width:37px}.touch-pad>button{width:40px;margin-left:39px}.touch-actions #touch-fire{width:66px;height:66px}.touch-actions button{height:42px;min-width:42px}.touch-actions #touch-reload{font-size:18px}.pickup-banner{bottom:24%;font-size:13px}}
@media(max-height:500px){.topline{height:45px}.hud{top:50px}.title-card{padding:18px 26px}.title-card h1{font-size:65px;margin:16px 0 6px}.title-sub{margin-top:13px}.story{margin:10px 0 15px}.start-note{margin-top:9px}.title-stamp{top:18%}.title-footer{bottom:10px}.map-panel{top:130px}.bottom-hint{bottom:10px}}

(() => {
  'use strict';
  const canvas = document.getElementById('view');
  const ctx = canvas.getContext('2d', { alpha: false });
  const mapCanvas = document.getElementById('map');
  const mapCtx = mapCanvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const TAU = Math.PI * 2;
  const GRID = 21;
  const FOV = Math.PI / 3;
  let world, player, enemies, pickups, exit, gameState = 'title';
  let lastTime = 0, gameTime = 0, kills = 0, damageFlash = 0, muzzle = 0, toastTimer = 0;
  let audio = null, audioMuted = false, ambientGain = null;
  let zBuffer = new Float32Array(960);
  let fireHeld = false, mobile = false;
  const keys = new Set();
  const touch = { forward: false, back: false, left: false, right: false };
  const weapons = [
    { name: 'SERVICE PISTOL', type: '9MM BALL · SEMI-AUTO', magSize: 12, ammo: 12, reserve: 48, damage: 38, fireRate: .29, reload: 1.05, spread: .012, range: 13, sound: 'pistol' },
    { name: 'BREACHER 12G', type: '12 GAUGE · 8 PELLET', magSize: 6, ammo: 6, reserve: 18, damage: 12, fireRate: .72, reload: 1.35, spread: .09, range: 8, sound: 'shotgun' },
    { name: 'ARC CARBINE', type: 'PLASMA CELL · FULL AUTO', magSize: 24, ammo: 24, reserve: 72, damage: 18, fireRate: .105, reload: 1.45, spread: .025, range: 12, sound: 'rifle' }
  ];
  let weaponIndex = 0, fireCooldown = 0, reloadTimer = 0, hurtCooldown = 0;
  const sprites = {};

  function randomGenerator(seed) {
    let state = seed >>> 0;
    return () => { state = (state * 1664525 + 1013904223) >>> 0; return state / 4294967296; };
  }
  const rand = randomGenerator(93417);
  function makeWorld() {
    const grid = Array.from({ length: GRID }, () => Array(GRID).fill(1));
    const visited = new Set(['1,1']);
    const stack = [[1, 1]];
    grid[1][1] = 0;
    while (stack.length) {
      const [x, y] = stack[stack.length - 1];
      const choices = [[0,-2],[2,0],[0,2],[-2,0]].filter(([dx,dy]) => {
        const nx=x+dx, ny=y+dy; return nx>0&&ny>0&&nx<GRID-1&&ny<GRID-1&&!visited.has(`${nx},${ny}`);
      });
      if (!choices.length) { stack.pop(); continue; }
      const [dx,dy] = choices[Math.floor(rand()*choices.length)];
      grid[y+dy/2][x+dx/2] = 0; grid[y+dy][x+dx] = 0;
      visited.add(`${x+dx},${y+dy}`); stack.push([x+dx,y+dy]);
    }
    // Break selected walls into wider intersections and short loops.
    for (let y=2;y<GRID-2;y++) for(let x=2;x<GRID-2;x++) {
      if (grid[y][x] && rand()<.065 && ((grid[y-1][x]===0&&grid[y+1][x]===0)||(grid[y][x-1]===0&&grid[y][x+1]===0))) grid[y][x]=0;
    }
    // A few open chambers make landmarks and give fights room to breathe.
    [[5,5],[15,5],[5,15],[15,15],[10,10]].forEach(([cx,cy]) => {
      for(let y=cy-1;y<=cy+1;y++) for(let x=cx-1;x<=cx+1;x++) if(x>0&&y>0&&x<GRID-1&&y<GRID-1) grid[y][x]=0;
    });
    return grid;
  }
  function isWall(x,y) { return x<0||y<0||x>=GRID||y>=GRID||world[Math.floor(y)][Math.floor(x)]!==0; }
  function makeSprite(type, variant=0) {
    const c=document.createElement('canvas'); c.width=96; c.height=112; const g=c.getContext('2d');
    if(type==='enemy') {
      const hue=[0,12,110,280][variant%4];
      g.shadowColor=`hsla(${hue},90%,45%,.45)`;g.shadowBlur=14;
      const body=g.createRadialGradient(44,55,5,49,66,45);body.addColorStop(0,`hsl(${hue},24%,43%)`);body.addColorStop(.58,`hsl(${hue},35%,21%)`);body.addColorStop(1,'#111512');
      g.fillStyle=body;g.beginPath();g.moveTo(20,97);g.lineTo(15,76);g.lineTo(22,51);g.lineTo(30,34);g.lineTo(45,28);g.lineTo(62,34);g.lineTo(75,54);g.lineTo(82,81);g.lineTo(72,98);g.lineTo(58,104);g.lineTo(35,103);g.closePath();g.fill();g.shadowBlur=0;
      g.fillStyle='#19201c';g.beginPath();g.ellipse(48,50,27,24,0,0,TAU);g.fill();
      g.fillStyle='#69736b';g.beginPath();g.moveTo(24,43);g.lineTo(12,21);g.lineTo(34,34);g.moveTo(61,33);g.lineTo(78,17);g.lineTo(71,45);g.fill();
      const eyeGlow=g.createRadialGradient(37,49,1,37,49,9);eyeGlow.addColorStop(0,'#fff7d1');eyeGlow.addColorStop(.3,'#ff4539');eyeGlow.addColorStop(1,'#8e100b00');g.fillStyle=eyeGlow;g.beginPath();g.arc(37,49,9,0,TAU);g.fill();
      const eyeGlow2=g.createRadialGradient(60,48,1,60,48,9);eyeGlow2.addColorStop(0,'#fff7d1');eyeGlow2.addColorStop(.3,'#ff4539');eyeGlow2.addColorStop(1,'#8e100b00');g.fillStyle=eyeGlow2;g.beginPath();g.arc(60,48,9,0,TAU);g.fill();
      g.fillStyle='#1b0807';g.beginPath();g.ellipse(49,67,13,6,0,0,TAU);g.fill();g.strokeStyle='#d2c8a9';g.lineWidth=2;for(let i=0;i<5;i++){g.beginPath();g.moveTo(39+i*5,64);g.lineTo(40+i*5,71);g.stroke();}
      g.fillStyle='#788077';g.fillRect(23,83,49,7);g.fillStyle='#cf493b';g.fillRect(29,84,6,4);g.fillRect(58,84,7,4);
      g.fillStyle='#111712';g.fillRect(28,94,12,12);g.fillRect(57,94,12,12);
    } else if(type==='exit') {
      g.shadowColor='#d4ff67';g.shadowBlur=20;g.strokeStyle='#d4ff67';g.lineWidth=4;g.strokeRect(17,9,62,97);g.shadowBlur=0;g.fillStyle='#1b2c1a';g.fillRect(23,15,50,88);g.fillStyle='#b7ef68';g.globalAlpha=.18;g.fillRect(26,18,44,82);g.globalAlpha=1;
      g.fillStyle='#d4ff67';g.font='bold 14px monospace';g.textAlign='center';g.fillText('LIFT',48,42);g.font='bold 26px monospace';g.fillText('↓',48,76);g.fillStyle='#efffd0';g.fillRect(21,101,54,4);
    } else {
      g.shadowColor='#d4ff67';g.shadowBlur=13;g.translate(48,54);g.rotate(Math.PI/4);g.fillStyle=type==='ammo'?'#d4ff67':type==='health'?'#ef5c4d':type==='armor'?'#7dd4e0':'#b591ff';g.fillRect(-18,-18,36,36);g.fillStyle='#101611';g.fillRect(-12,-12,24,24);g.shadowBlur=0;g.fillStyle=type==='health'?'#fff':type==='ammo'?'#ecffad':type==='armor'?'#d5faff':'#ede0ff';
      if(type==='health'){g.fillRect(-3,-10,6,20);g.fillRect(-10,-3,20,6);}else if(type==='ammo'){g.fillRect(-7,-9,5,18);g.fillRect(2,-9,5,18);g.fillStyle='#7d9a42';g.fillRect(-7,-10,5,4);g.fillRect(2,-10,5,4);}else if(type==='armor'){g.beginPath();g.moveTo(0,-11);g.lineTo(9,-7);g.lineTo(8,3);g.lineTo(0,11);g.lineTo(-8,3);g.lineTo(-9,-7);g.closePath();g.fill();}else{g.font='bold 18px monospace';g.textAlign='center';g.textBaseline='middle';g.fillText('✦',0,1);}
    }
    return c;
  }
  sprites.enemy=[0,1,2,3].map((v)=>makeSprite('enemy',v));
  sprites.ammo=makeSprite('ammo');sprites.health=makeSprite('health');sprites.armor=makeSprite('armor');sprites.cell=makeSprite('cell');sprites.exit=makeSprite('exit');

  function initGame() {
    world=makeWorld(); player={x:1.5,y:1.5,angle:.12,health:100,armor:25,walk:0,damage:0};
    enemies=[];pickups=[];kills=0;gameTime=0;weaponIndex=0;fireCooldown=0;reloadTimer=0;hurtCooldown=0;
    weapons[0].ammo=12;weapons[0].reserve=48;weapons[1].ammo=6;weapons[1].reserve=18;weapons[2].ammo=24;weapons[2].reserve=72;
    const cells=[];
